if set(_ROWS) != set(LANGUAGES):
    raise RuntimeError("Owner panel translations are missing a supported locale.")
for _locale, _values in _ROWS.items():
    if len(_values) != len(KEYS):
        raise RuntimeError(f"Owner panel translation mismatch for {_locale}.")
CATALOG = {locale: dict(zip(KEYS, values, strict=True)) for locale, values in _ROWS.items()}

def translate_owner_panel(language: str | None, key: str, **values: object) -> str:
    locale = normalize_language(language)
    template = CATALOG[locale].get(key, key)
    try:
        return template.format(**values)
    except (KeyError, ValueError):
        return template
